@pytest.mark.parametrize("version", [v975, v1001], ids=lambda version: version.__name__.rpartition(".")[2])
def test_boss_event_is_packet_74(version):
    assert version.PACKETS[74] is version.BossEventPacket


@pytest.mark.parametrize(("event_type", "golden"), V975_GOLDENS)
def test_boss_event_v975_gating_selects_the_payload_per_event_type(event_type, golden):
    packet = v975.BossEventPacket(
        boss_id=-3,
        player_id=7,
        event_type=event_type,
        name="boss",
        filtered_name="bo**",
        health_percent=0.5,
        darken_screen=2,
        create_world_fog=0,
        color=v975.BossBarColor.GREEN,
        overlay=v975.BossBarOverlay.NOTCHED_6,
    )
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), V975_DECODED)
def test_boss_event_v975_decodes_each_gated_shape_and_defaults_the_rest(packet, golden):
    assert v975.BossEventPacket.from_bytes(golden) == packet


@pytest.mark.parametrize("golden", [V975_ADD, V975_PLAYER_ADDED, V975_REMOVE, V975_UPDATE_STYLE])
def test_boss_event_v975_re_encodes_each_gated_shape(golden):
    assert bytes(v975.BossEventPacket.from_bytes(golden)) == golden


@pytest.fixture
def v1001_add():
    return v1001.BossEventPacket(
        boss_id=-3,
        player_id=7,
        event_type=v1001.BossEventUpdateType.ADD,
        name="boss",
        filtered_name="bo**",
        health_percent=0.5,
        color=v1001.BossBarColor.GREEN,
        overlay=v1001.BossBarOverlay.NOTCHED_6,
    )


def test_boss_event_v1001_encodes_to_its_golden(v1001_add):
    assert bytes(v1001_add) == V1001_ADD


def test_boss_event_v1001_decodes_from_its_golden(v1001_add):
    assert v1001.BossEventPacket.from_bytes(V1001_ADD) == v1001_add


@pytest.mark.parametrize(("event_type", "golden"), V1001_GOLDENS)
def test_boss_event_v1001_writes_every_event_type_the_same_way(v1001_add, event_type, golden):
    v1001_add.event_type = event_type
    assert bytes(v1001_add) == golden


def test_a_v975_remove_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.BossEventPacket.from_bytes(V975_REMOVE)


@pytest.fixture
def v2193_add():
    return v2193.BossEventPacket(
        boss_id=-3,
        event_type=v2193.BossEventUpdateType.ADD,
        name="boss",
        filtered_name="bo**",
        health_percent=0.5,
        color=v2193.BossBarColor.GREEN,
        overlay=v2193.BossBarOverlay.NOTCHED_6,
    )


def test_boss_event_v2193_drops_the_player_id(v2193_add):
    assert bytes(v2193_add) == V1001_ADD[:1] + V1001_ADD[2:]


def test_boss_event_v2193_decodes_its_own_body(v2193_add):
    assert v2193.BossEventPacket.from_bytes(bytes(v2193_add)) == v2193_add


def test_a_v1001_boss_event_body_leaves_bytes_over_as_a_v2193_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2193.BossEventPacket.from_bytes(V1001_ADD)
